--- src/bus.ts ---
/**
 * Hook bus for harness plugins (OpenCode-style hooks). The README states the contract:
 * handlers run one after another in subscription order, emit resolves after all of them,
 * a handler error rejects emit, and unsubscribing during an emit does not stop the others.
 */

export type Handler<T> = (payload: T) => void | Promise<void>;

export class HookBus {
  private handlers: Map<string, Handler<unknown>[]> = new Map();

  /** Subscribes a handler to an event; returns the function that unsubscribes it. */
  on<T>(event: string, handler: Handler<T>): () => void {
    const list = this.handlers.get(event) ?? [];
    list.push(handler as Handler<unknown>);
    this.handlers.set(event, list);
    return () => {
      const index = list.indexOf(handler as Handler<unknown>);
      if (index >= 0) {
        list.splice(index, 1);
      }
    };
  }

  /** Runs the handlers of an event with the payload. */
  async emit<T>(event: string, payload: T): Promise<void> {
    // Snapshot at emit start: unsubscribing during an emit affects only later emits.
    const snapshot = [...(this.handlers.get(event) ?? [])];
    for (const handler of snapshot) {
      // Sequential await: each handler settles before the next starts, errors
      // propagate to the caller of emit, and later handlers are skipped on error.
      await handler(payload);
    }
  }

  /** How many handlers an event has. */
  count(event: string): number {
    return (this.handlers.get(event) ?? []).length;
  }
}


--- tmp/verify.ts ---
import assert from "node:assert/strict";
import { HookBus } from "../src/bus.ts";
import { registerAuditPlugin } from "../src/plugin.ts";

// ordering + await + emit resolves after all handlers
{
  const bus = new HookBus();
  const seen: string[] = [];
  bus.on("e", async () => { await new Promise(r => setTimeout(r, 15)); seen.push("a"); });
  bus.on("e", () => { seen.push("b"); });
  await bus.emit("e", null);
  assert.deepEqual(seen, ["a", "b"], "sequential order + awaited");
}

// error rejects emit and stops later handlers
{
  const bus = new HookBus();
  const err = new Error("boom");
  let later = false;
  bus.on("e", async () => { await Promise.resolve(); throw err; });
  bus.on("e", () => { later = true; });
  await assert.rejects(() => bus.emit("e", null), (e) => e === err);
  assert.equal(later, false, "later handler skipped on error");
}

// synchronous throw also rejects emit
{
  const bus = new HookBus();
  const err = new Error("sync");
  bus.on("e", () => { throw err; });
  await assert.rejects(() => bus.emit("e", null), (e) => e === err);
}

// unsubscribe during emit affects only the next emit
{
  const bus = new HookBus();
  const seen: string[] = [];
  const off2 = bus.on("e", () => seen.push("second"));
  bus.on("e", () => { off2(); seen.push("first"); });
  await bus.emit("e", null);
  assert.deepEqual(seen, ["second", "first"]);
  seen.length = 0;
  await bus.emit("e", null);
  assert.deepEqual(seen, ["first"]);
}

// one-time notice self-unsubscribes but still completes the current emit
{
  const bus = new HookBus();
  const audit: string[] = [];
  registerAuditPlugin(bus, audit);
  const result = { tool: "read", output: "pw password=hunter2 ok" };
  await bus.emit("tool.after", result);
  assert.equal(result.output, "pw password=[redacted] ok");
  assert.deepEqual(audit, [
    "notice: tool output is audited",
    "read: pw password=[redacted] ok",
  ]);
  audit.length = 0;
  await bus.emit("tool.after", { tool: "write", output: "clean" });
  assert.deepEqual(audit, ["write: clean"], "notice only once");
}

console.log("all contract checks passed");
